def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with the current working directory or root
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append the component
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if this path is a symlink
            if current in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[current]

                # Determine where resolution continues from
                if target.startswith('/'):
                    # Absolute symlink target
                    current = '/'
                    remaining = target[1:]
                else:
                    # Relative symlink target - relative to the directory containing the link
                    if current != '/':
                        current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                    remaining = target

                # Break inner loop to process the new remaining path
                break
        else:
            # We've processed all components without hitting a symlink
            break

    # Handle the result
    if current == '/':
        return '/'
    else:
        # Remove any trailing slash (shouldn't happen, but be safe)
        return current.rstrip('/')

